#include"get_next_line.h"

/*
The examples/gnl_tester/ is made by other people who 
make this get next line tester Git repository.
https://github.com/Tripouille/gnlTester/tree/master
*/

int	main(void)
{
	size_t			i = 0;
	size_t			score = 0;
	size_t			max_score = 14;
	t_gnl_tester	arr[] = {
		{
			// 0
			(const char *)"test/get_next_line/input/41_no_nl",
			(const char *[]){"01234567890123456789012345678901234567890", NULL},
		},
		{
			// 1
			(const char *)"test/get_next_line/input/41_with_nl",
			(const char *[]){"0123456789012345678901234567890123456789\n", "0", NULL},
		},
		{
			// 2
			(const char *)"test/get_next_line/input/42_no_nl",
			(const char *[]){"012345678901234567890123456789012345678901", NULL},
		},
		{
			// 3
			(const char *)"test/get_next_line/input/42_with_nl",
			(const char *[]){"01234567890123456789012345678901234567890\n", "1", NULL},
		},
		{
			// 4
			(const char *)"test/get_next_line/input/43_no_nl",
			(const char *[]){"0123456789012345678901234567890123456789012", NULL},
		},
		{
			// 5
			(const char *)"test/get_next_line/input/43_with_nl",
			(const char *[]){"012345678901234567890123456789012345678901\n", "2", NULL},
		},
		{
			// 6
			(const char *)"test/get_next_line/input/alternate_line_nl_no_nl",
			(const char *[]){
				"98765432109876543210987654321098765432109\n",
				"\n",
				"012345678901234567890123456789012345678901\n",
				"\n",
				"9876543210987654321098765432109876543210987\n",
				"\n",
				"012345678901234567890123456789012345678901\n",
				"\n",
				"98765432109876543210987654321098765432109",
				NULL
			},
		},
		{
			// 7
			(const char *)"test/get_next_line/input/alternate_line_nl_with_nl",
			(const char *[]){
				"01234567890123456789012345678901234567890\n",
				"\n",
				"987654321098765432109876543210987654321090\n",
				"\n",
				"0123456789012345678901234567890123456789012\n",
				"\n",
				"987654321098765432109876543210987654321090\n",
				"\n",
				"01234567890123456789012345678901234567890\n",
				NULL
			},
		},
		{
			// 8
			(const char *)"test/get_next_line/input/big_line_no_nl",
			(const char *[]){"", NULL},
		},
		{
			// 9
			(const char *)"test/get_next_line/input/empty",
			(const char *[]){NULL},
		},
		{
			// 10
			(const char *)"test/get_next_line/input/multiple_line_no_nl",
			(const char *[]){
				"01234567890123456789012345678901234567890\n",
				"987654321098765432109876543210987654321098\n",
				"0123456789012345678901234567890123456789012\n",
				"987654321098765432109876543210987654321098\n",
				"01234567890123456789012345678901234567890",
				NULL
			},
		},
		{
			// 11
			(const char *)"test/get_next_line/input/multiple_line_with_nl",
			(const char *[]){
				"9876543210987654321098765432109876543210\n",
				"01234567890123456789012345678901234567890\n",
				"987654321098765432109876543210987654321098\n",
				"01234567890123456789012345678901234567890\n",
				"9876543210987654321098765432109876543210\n",
				NULL
			},
		},
		{
			// 12
			(const char *)"test/get_next_line/input/multiple_nlx5",
			(const char *[]){"\n", "\n", "\n", "\n", "\n", NULL},
		},
		{
			// 13
			(const char *)"test/get_next_line/input/nl",
			(const char *[]){"\n", NULL},
		},
	};

	while (i < max_score)
	{
		if (assert_next_line(&arr[i]) == true)
			score += 1;
		else
		{
			write(1, ">>> ", 4);
			write_int(i, "0123456789", 1);
			write(1, "\n", 1);
		}
		i += 1;
	}
	write_score(score, max_score);
	return (0);
}

/*
valgrind --leak-check=full --show-leak-kinds=all ./test/out/get_next_line/test.out
*/
